/**
 * 游乐场「行情回放」用的历史日线 —— **纯数据 + 解析**，不含任何业务逻辑。
 *
 * 三个大盘指数，2019-01-02 起到 2026-09 月，全部打包进安装包：游乐场的价值在
 * "同一批行情下比较不同模型 / 不同策略的表现"，运行时去拉数据会让结果不可复现，
 * 还会给一个本来能离线跑的场景加上网络依赖。
 *
 * 数据来源：Yahoo Finance chart 接口（`query1.finance.yahoo.com/v8/finance/chart/<code>`，
 * `interval=1d`），按下面的 `code` 各取一次。要刷新到更近的日期，就用同一个接口重拉，
 * 按本文件的行格式重新生成即可。
 *
 * 行格式（一行一根日线，空格分隔，按日期升序）：
 *   `yymmdd open high low close volume`
 * - 四个价格都**取整**：指数点位取整的相对误差在万分之一量级，而游乐场只关心涨跌
 *   与相对位置，留两位小数只是把文件撑大一倍；
 * - `volume` 是原始成交量除以一百万。**注意各市场口径不同**（美 / 港是股数，沪是
 *   交易所自己的手数口径），所以界面与发给模型的 `state` 一律只用**相对量**
 *   （对 20 日均量的倍数），不声称任何绝对单位。
 */

export type MarketSymbol = "shc" | "hsi" | "spx";

/** 一根日线。`date` 是 `YYYY-MM-DD`（交易日，非交易日不在表里）。 */
export type MarketBar = {
  date: string;
  open: number;
  high: number;
  low: number;
  close: number;
  /** 原始成交量 / 1e6，口径随市场而异 —— 只做相对比较，见文件头。 */
  volume: number;
};

export type MarketMeta = {
  symbol: MarketSymbol;
  /** 数据源里的代码，会原样写进发给模型的 `state`。 */
  code: string;
  /** 英文名：发给模型的那一份（`state` 里的文本一律英文）。 */
  name: string;
  market: string;
  currency: string;
  /** 界面名走 i18n。 */
  nameKey: string;
};

export const MARKET_SYMBOLS: readonly MarketSymbol[] = ["shc", "hsi", "spx"];

export const MARKET_META: Record<MarketSymbol, MarketMeta> = {
  shc: {
    symbol: "shc",
    code: "000001.SS",
    name: "SSE Composite Index",
    market: "Shanghai",
    currency: "CNY",
    nameKey: "jev.playground.market.symbol.shc",
  },
  hsi: {
    symbol: "hsi",
    code: "^HSI",
    name: "Hang Seng Index",
    market: "Hong Kong",
    currency: "HKD",
    nameKey: "jev.playground.market.symbol.hsi",
  },
  spx: {
    symbol: "spx",
    code: "^GSPC",
    name: "S&P 500",
    market: "United States",
    currency: "USD",
    nameKey: "jev.playground.market.symbol.spx",
  },
};

