/** 解析结果缓存：一份行情解析一次（近两千行 × 三个市场，别每次取窗口都重来）。 */
const PARSED = new Map<MarketSymbol, readonly MarketBar[]>();

/** 文本 → 日线数组。坏行（字段数不对、数字解析不出来）直接跳过而不是抛： */
function parseSeries(text: string): MarketBar[] {
  const bars: MarketBar[] = [];
  for (const line of text.trim().split("\n")) {
    const parts = line.split(" ");
    if (parts.length !== 6) continue;
    const [stamp, open, high, low, close, volume] = parts as [string, string, string, string, string, string];
    if (stamp.length !== 6) continue;
    const bar: MarketBar = {
      date: `20${stamp.slice(0, 2)}-${stamp.slice(2, 4)}-${stamp.slice(4, 6)}`,
      open: Number(open),
      high: Number(high),
      low: Number(low),
      close: Number(close),
      volume: Number(volume),
    };
    if (!Number.isFinite(bar.open) || !Number.isFinite(bar.high)) continue;
    if (!Number.isFinite(bar.low) || !Number.isFinite(bar.close)) continue;
    bars.push(bar);
  }
  return bars;
}

/** 某个指数的全部日线（升序）。 */
export function marketBars(symbol: MarketSymbol): readonly MarketBar[] {
  const cached = PARSED.get(symbol);
  if (cached) return cached;
  const parsed = parseSeries(SERIES_TEXT[symbol]);
  PARSED.set(symbol, parsed);
  return parsed;
}

/** 这份行情覆盖的日期区间（`YYYY-MM-DD`）—— 日期选择器的 min / max。 */
export function marketSpan(symbol: MarketSymbol): { first: string; last: string } {
  const bars = marketBars(symbol);
  const first = bars[0]?.date ?? "";
  const last = bars[bars.length - 1]?.date ?? "";
  return { first, last };
}

/**
 * 一次回放最多几根 —— 每根一次 `systemoneRun`，250 根已经是"跑一次要等一会儿"
 * 的量级了。用户把区间拉得更大时，界面按这个数截断并明说截了（见 `clampMarketWindow`）。
 */
export const MARKET_MAX_BARS = 250;

export type MarketWindow = {
  /** 落在区间里的日线（升序）；区间里一根都没有时是空数组。 */
  bars: readonly MarketBar[];
  /** 第一根在全量序列里的下标 —— 指标要往区间之前回看，靠它定位。 */
  offset: number;
  /** 用户要的区间里实际有多少根（可能大于 `bars.length`）。 */
  available: number;
  /** 是否因为 `MARKET_MAX_BARS` 截断过。 */
  truncated: boolean;
};

/**
 * 取回放窗口：日期区间 → 日线。
 *
 * 两端都是闭区间，`from > to` 时自动对调（日期选择器上很容易点反）。超过上限时
 * **保留靠前的部分**：回放是从头往后走的，截掉尾巴比截掉开头符合直觉。
 */
export function clampMarketWindow(symbol: MarketSymbol, from: string, to: string): MarketWindow {
  const bars = marketBars(symbol);
  const lo = from <= to ? from : to;
  const hi = from <= to ? to : from;
  let offset = bars.findIndex((bar) => bar.date >= lo);
  if (offset < 0) offset = bars.length;
  let end = offset;
  while (end < bars.length && (bars[end] as MarketBar).date <= hi) end++;
  const available = end - offset;
  const truncated = available > MARKET_MAX_BARS;
  return {
    bars: bars.slice(offset, offset + Math.min(available, MARKET_MAX_BARS)),
    offset,
    available,
    truncated,
  };
}

/** 默认区间：最后 60 个交易日 —— 够看出一段趋势，又不至于一跑就是几百次判定。 */
export const MARKET_DEFAULT_BARS = 60;

export function defaultMarketRange(symbol: MarketSymbol): { from: string; to: string } {
  const bars = marketBars(symbol);
  if (bars.length === 0) return { from: "", to: "" };
  const start = Math.max(0, bars.length - MARKET_DEFAULT_BARS);
  return { from: (bars[start] as MarketBar).date, to: (bars[bars.length - 1] as MarketBar).date };
}
